function main(input) {
  var low = (input.items || []).filter(function (r) {
    return Number(r.data.qty) < Number(r.data.reorder_point);
  });
  return {
    rows: low.map(function (r) {
      return { data: { code: r.data.code, name: r.data.name, order_qty: r.data.reorder_qty, status: "下書き" } };
    }),
    csv: low.map(function (r) {
      return { "品番": String(r.data.code), "品名": String(r.data.name), "発注数": String(r.data.reorder_qty) };
    })
  };
}

function main(input) {
  var lines = (input.items || []).map(function (r) {
    return "- " + r.data.code + " " + r.data.borrower + "（返却予定日 " + r.data.due_on + "）";
  });
  return { text: "# 延滞の一覧（" + input.date + "）\n\n" + (lines.length ? lines.join("\n") : "延滞はありません。") + "\n" };
}

